insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000099080', '$\frac{1}{5}\ln\left|\frac{x}{x+5}\right|+C$', 'A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. O denominador possui dois fatores lineares distintos; decomponha a fração antes de integrar. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
