insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000991001', '40000000-0000-4000-8000-000000099100', 'Leia o objetivo', 'Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.', 1), ('70000000-0000-4000-8000-000000991002', '40000000-0000-4000-8000-000000099100', 'Reconheça a ideia', 'Como $p=6>1$, trata-se de uma integral de potência convergente.', 2), ('70000000-0000-4000-8000-000000991003', '40000000-0000-4000-8000-000000099100', 'Escreva a relação', 'Registre a definição, fórmula ou teste que se aplica antes de simplificar.', 3), ('70000000-0000-4000-8000-000000991004', '40000000-0000-4000-8000-000000099100', 'Desenvolva a análise', 'Execute a transformação necessária e obtenha: Converge e vale $\frac{1}{5}$.', 4), ('70000000-0000-4000-8000-000000991005', '40000000-0000-4000-8000-000000099100', 'Confira a conclusão', 'Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
